"""Generate the dependency-free NFKC tables from Python's Unicode database."""
from pathlib import Path
import unicodedata as ucd


def generate():
    lines = [
        '// Generated by tool/generate_unicode_data.py; do not edit.',
        f'// Unicode database version: {ucd.unidata_version}.',
        '// Hangul decomposition and composition are algorithmic.',
        '',
        'const nfkdMappings = <int, List<int>>{',
    ]
    classes = []
    compositions = []
    uppercase = []
    for scalar in range(0x110000):
        char = chr(scalar)
        decomposed = ucd.normalize('NFKD', char)
        if decomposed != char and not 0xAC00 <= scalar <= 0xD7A3:
            values = ', '.join(hex(ord(c)) for c in decomposed)
            lines.append(f'  {hex(scalar)}: [{values}],')
        combining = ucd.combining(char)
        if combining:
            classes.append(f'  {hex(scalar)}: {combining},')
        upper = char.upper()
        if upper != char:
            values = ', '.join(hex(ord(c)) for c in upper)
            uppercase.append(f'  {hex(scalar)}: [{values}],')
        canonical = ucd.decomposition(char)
        if canonical and not canonical.startswith('<'):
            pair = [int(value, 16) for value in canonical.split()]
            if len(pair) == 2 and ucd.normalize('NFC', ''.join(map(chr, pair))) == char:
                key = pair[0] * 0x110000 + pair[1]
                compositions.append(f'  {hex(key)}: {hex(scalar)},')
    lines += ['};', '', 'const combiningClasses = <int, int>{']
    lines += classes
    lines += ['};', '', 'const canonicalCompositions = <int, int>{']
    lines += compositions
    lines += ['};', '', 'const uppercaseMappings = <int, List<int>>{']
    lines += uppercase
    lines += ['};', '']
    target = Path(__file__).resolve().parents[1] / 'lib/src/unicode_data.dart'
    target.write_text('\n'.join(lines), encoding='utf-8')
    print(f'Generated {target.name}: Unicode {ucd.unidata_version}')


if __name__ == '__main__':
    generate()
